// Dashboard v3 wire contract (plan §0.5). Frozen after P0: change only with a contract-change commit.
// Go mirrors every type field for field (internal/query/types.go, internal/install/types.go, internal/meta/types.go);
// api/contract.golden.ts, generated by `go test ./internal/query -run Golden -update`, makes tsc fail on drift.

export type Env = 'production' | 'preview' | 'development' | 'all'
export type RangeKey = 'today' | 'yesterday' | 'wtd' | 'mtd' | 'lastmonth' | '7d' | '30d' | '90d' | '12mo' | `d:${string}` | `c:${string}~${string}`
export type CmpKey = 'prev' | 'none' | `c:${string}`
export type Dim =
  | 'path' | 'route' | 'host' | 'entry' | 'exit'
  | 'referrer' | 'source' | 'channel' | 'ai_source'
  | 'utm_source' | 'utm_medium' | 'utm_campaign' | 'utm_term' | 'utm_content'
  | 'country' | 'region' | 'city' | 'device' | 'browser' | 'os'
  | 'event' | 'goal' | 'dow' | 'hour'
export type Metric = 'visitors' | 'pageviews' | 'sessions' | 'duration' | 'bounce' | 'conversion' | 'revenue'
export interface Filter { dim: Dim; value: string }

export interface Basis { text: string; short: string; why: string; dates: string; custom: boolean; none: boolean }
export interface Window {
  key: string; label: string; from: number; to: number; prevFrom: number | null; prevTo: number | null
  bucket: 'hour' | 'day'; tz: string; elapsed: boolean; lastBucket: number; clamped: boolean; invalid: string; basis: Basis
}

export interface Features { revenue: boolean; crawlers: boolean; currency: string }
export interface Site { id: string; domain: string; origins: string[]; created: number; lastEventAt: number | null; events24h: number; features: Features }
export interface SiteStatus {
  lastEventAt: number | null; events24h: number; rejected24h: number
  geo: { source: 'db' | 'vercel' | 'cloudflare' | 'netlify'; share: number } | null // dominant location source over 24 h
}
export interface SiteSummary { id: string; domain: string; visitors: number; prevVisitors: number | null; online: number; spark: (number | null)[] }

export interface Totals {
  visitors: number; pageviews: number; sessions: number; durationMs: number; bounce: number
  conversions: number; convVisitors: number; convRate: number; baseVisitors: number
  revenueMinor: number; purchases: number
  eventPeople: number                   // people who sent at least one custom or outbound event
}
export interface Stats extends Totals {
  window: Window; prev: Totals | null; online: number
  botRequests: number | null            // null when crawler ingest is not set up
  conv: { goalId: number; name: string } | null
  agentSessions: number                 // AI agent sessions in range, whatever actor is
}
export interface Point { t: number; v: number | null }
export interface BucketExtra { t: number; topSources: { key: string; visitors: number }[]; conversions: number; revenueMinor: number }
export interface Series { window: Window; metric: Metric; bucket: 'hour' | 'day'; points: Point[]; prev: Point[]; extras?: BucketExtra[] }
export interface Note { id: number; site: string; ts: number; label: string; kind: 'deploy' | 'campaign' | 'press' | 'other' }

export interface Row {
  key: string; visitors: number; pageviews: number; total: number
  sessions?: number; bounce?: number; convRate?: number | null; revenueMinor?: number
  entries?: number; exits?: number; views?: number; exitRate?: number
  country?: string; region?: string; top?: string
}
export type ChangeItem =
  | { kind: 'day'; day: string; cur: number; prev: number; added: number; source: string | null; basis: string }
  | { kind: 'source'; key: string; cur: number; prev: number; basis: string }
  | { kind: 'rate'; metric: 'bounce' | 'conversion'; cur: number; prev: number; n: number; basis: string }
export interface Changes { items: ChangeItem[] }
export interface Heatmap {
  from: number; to: number; weeks: 4; cells: number[][] /* [7 dow, Mon=0][24 hour] */; max: number; total: number
  status: 'ok' | 'sparse'; threshold: 150; peak: { dow: number; hour: number; value: number } | null
  clear: boolean; busiest: { label: string; fromHour: number; toHour: number; dows: number[] } | null
}
export interface LiveEvent { ts: number; person: string; label: string; sessionId: string; type: string; path: string; name: string; country: string; city: string; source: string }
export interface Live {
  asOf: number; active: number; events5m: number
  countries: { key: string; count: number }[]; sources: { key: string; count: number }[]; pages: { key: string; count: number }[]
  stream: LiveEvent[]; streamTotal: number
}

export interface Person {
  person: string; label: string; identified: boolean; firstSeen: number; lastSeen: number; visits: number; visitsTotal: number
  pages: number; durationMs: number; country: string; region: string; city: string; device: string; browser: string; os: string; source: string
}
export interface SessionRow {
  sessionId: string; person: string; label: string; start: number; durationMs: number; pages: number; entry: string; exit: string
  source: string; country: string; city: string; device: string; browser: string; os: string; goals: number[]; revenueMinor: number
  agent: string                         // AI agent id, '' for people
}
export type StepType = 'pageview' | 'engage' | 'event' | 'identify' | 'error' | 'outbound' | 'form' | 'vital'
export interface Step { ts: number; type: StepType; path: string; name: string; engagedMs: number; scrollPct: number; props: Record<string, string | number | boolean> }
export interface GoalHit { id: number; name: string; ts: number }
export interface JourneySession {
  sessionId: string; start: number; source: string; steps: Step[]
  visit: number; durationMs: number; country: string; city: string; device: string; goals: GoalHit[]
  agent: string                         // AI agent id, '' for people
  via: AgentVia | ''                    // how the agent was recognised, '' for people
  verified: boolean                     // via is ip, relay or sig
}

export interface Campaign { source: string; medium: string; campaign: string; term: string; content: string; visitors: number; sessions: number; bounce: number; convRate: number | null; revenueMinor: number }
export interface AIReferral { key: string; visitors: number; sessions: number; topEntry: string; convRate: number | null; revenueMinor: number }

export interface EventProp { key: string; distinct: number; top: string[] }
export interface EventRow { name: string; kind: 'custom' | 'outbound'; count: number; people: number; lastSeen: number; props: EventProp[] }
export interface EventDetail {
  name: string; count: number; people: number; prev: { count: number; people: number } | null
  series: Point[]; prevSeries: Point[]
  props: { key: string; rows: { value: string; count: number; people: number }[] }[]
  latest: { ts: number; person: string; label: string; sessionId: string; props: Record<string, string | number | boolean> }[]
}

export interface Goal { id: number; name: string; kind: 'page' | 'event'; match: string }
export interface GoalStats { conversions: number; visitors: number; rate: number }
export interface GoalRow extends Goal, GoalStats { prev: GoalStats }
export interface FirstTouchRow { key: string; converted: number; share: number; visitors: number; rate: number; lowBase: boolean; revenueMinor: number }
export interface GoalDetail {
  goal: Goal; cur: GoalStats; prev: GoalStats | null; series: Point[]; prevSeries: Point[]
  sources: FirstTouchRow[]; landings: FirstTouchRow[]; byVisit: { first: number; second: number; later: number }
}
export interface PathRow { steps: string[]; people: number; share: number }
export interface PathsReport { goal: Goal; converters: number; rows: PathRow[] }

export interface FunnelStep { kind: 'page' | 'event'; match: string; label: string }
export interface Funnel { id: number; name: string; windowMs: number; steps: FunnelStep[]; created: number }
export interface FunnelStepResult { label: string; reached: number; leftAfter: number; fromStart: number; fromPrev: number; medianMsFromPrev: number | null }
export interface FunnelReport { funnel: Funnel; window: Window; started: number; steps: FunnelStepResult[]; biggestDrop: { after: number; people: number } | null }
export interface DropoffPerson { person: string; label: string; lastVisit: number; exitPage: string; source: string }

export interface Money { netMinor: number; purchases: number; buyers: number; aovMinor: number }
export interface Purchase { ts: number; person: string; label: string; sessionId: string; amountMinor: number; plan: string; visitsBefore: number }
export interface Revenue { currency: string; otherCurrencyPurchases: number; cur: Money; prev: Money | null; series: Point[]; prevSeries: Point[]; purchases: Purchase[] }
export interface RevenueRow { key: string; revenueMinor: number; purchases: number; buyers: number; share: number }

export type CrawlCategory = 'training' | 'indexing' | 'fetch' | 'general'
export interface Crawlers {
  configured: boolean; window: Window; total: number; prevTotal: number | null
  categories: { key: CrawlCategory; requests: number; prev: number | null }[]
  providers: { provider: string; crawlers: { name: string; category: CrawlCategory; requests: number; prev: number | null }[] }[]
  series: { t: number; training: number; indexing: number; fetch: number; general: number }[]
  pages: { path: string; provider: string; crawler: string; category: CrawlCategory; requests: number; lastSeen: number; share: number }[]
}

export type ReasonCode =
  | 'ok' | 'fetch_failed' | 'script_missing' | 'wrong_site_id' | 'wrong_host' | 'csp_blocked'
  | 'origin_not_allowed' | 'no_events' | 'events_preview_only' | 'bot_filtered' | 'retries_high'
export interface CheckItem { id: 'page' | 'script' | 'csp' | 'origin' | 'first_event' | 'delivery'; label: string; status: 'pass' | 'fail' | 'warn' | 'pending'; code: ReasonCode; detail: string; fix: string }
export interface InstallCheck { state: 'waiting' | 'receiving' | 'blocked'; checkedAt: number; lastEventAt: number | null; checks: CheckItem[] }

export type TokenScope = 'read' | 'notes' | 'write' | 'crawl'
export interface ApiToken { id: string; name: string; prefix: string; scope: TokenScope; site: string | null; created: number; lastUsed: number | null; fromEnv: boolean }
export interface NewToken extends ApiToken { token: string }
export interface WhoAmI { name: string; scope: TokenScope; site: string | null }
export interface Share { id: string; label: string; site: string; state: string; hideRevenue: boolean; created: number; expires: number | null; lastUsed: number | null; url?: string }
export interface ShareMeta { site: Site; state: string; hideRevenue: boolean; expires: number | null }
export interface SavedView { id: number; name: string; site: string | null; state: string; created: number }
/** Which IP database answers lookups: the built-in DB-IP Lite Country file, a TRAIL_GEO_DB file, or none. */
export interface GeoInfo { source: 'embedded-country' | 'custom' | 'none'; build: string }
export interface Config { version: string; tz: string; demo: boolean; geo: GeoInfo; ingestRps: number; envSites: string[]; envTokens: number; dbFile: string }

// ---- AI visibility, agents and setup (AI agents plan §0.4). Frozen after P0. ----
export type AgentVia = 'ua' | 'ip' | 'relay' | 'sig'
export type AIStepKey = 'crawled' | 'fetched' | 'cited' | 'visited' | 'converted'
export interface AIFunnelStep { key: AIStepKey; unit: 'requests' | 'sessions' | 'people'; value: number | null; prev: number | null; status: 'ok' | 'not_set_up' | 'no_source' | 'no_goal' }
export interface AIProviderRow { provider: string; crawled: number; fetched: number; visited: number; converted: number | null }
export interface AIPageRow { path: string; crawled: number; fetched: number; visits: number; conversions: number | null; lastCrawled: number | null }
export interface AIVisibility { window: Window; steps: AIFunnelStep[]; providers: AIProviderRow[]; pages: AIPageRow[]; conv: { goalId: number; name: string } | null; verifiedShare: number | null }
export interface AgentRow { agent: string; name: string; provider: string; sessions: number; prev: number | null; pageviews: number; verified: number; lastSeen: number }
export interface AgentPoint { t: number; verified: number; claimed: number }
export interface AgentPage { path: string; pageviews: number; sessions: number; topAgent: string }
export interface AgentSession { sessionId: string; person: string; agent: string; name: string; provider: string; via: AgentVia; start: number; durationMs: number; pages: number; entry: string; goals: number }
export interface Agents {
  window: Window; sessions: number; prevSessions: number | null; pageviews: number; verifiedSessions: number; conversions: number
  conv: { goalId: number; name: string } | null; series: AgentPoint[]; agents: AgentRow[]; pages: AgentPage[]; latest: AgentSession[]
}
export interface AIList { name: string; kind: 'ip' | 'keys'; fetchedAt: number | null; entries: number; ok: boolean }
export interface AISetup {
  crawls: { state: 'none' | 'receiving' | 'quiet'; lastAt: number | null; last24h: number }
  agents: { lastAt: number | null; last24h: number }
  lists: AIList[]
}
